alias extext='gnome-screenshot -a -f /tmp/ocr-temp.png && text=$(tesseract /tmp/ocr-temp.png - 2>/dev/null) && echo "$text" | xclip -selection clipboard && len=$(printf %s "$text" | wc -m) && if [ "$len" -le 60 ]; then preview="$text"; else preview="$(printf %s "$text" | cut -c1-30) ... $(printf %s "$text" | cut -c$((len-29))-$len)"; fi && notify-send "OCR Copied" "$preview"'